pub(super) fn consume(request: &UnitRequest<'_>, result: &mut Handoff) -> Result<(), String> {
    let unit = request.unit;
    if !unit.compiler_advisory_only
        || unit.extraction_profile != request.capture.plan.extraction_profile
    {
        return Err("Compiler advisory unit mode or extraction profile disagrees with plan".into());
    }

    let snapshot = Stage::new("cli.advisory.load_inventory", &unit.target.package, None)
        .observe(|| capture::load_inventory(unit))?;
    let stage = Stage::new(
        "cli.advisory.decode",
        &unit.target.package,
        Some(snapshot.bundle.bytes()),
    );
    if header_only(request.args) {
        let facts = stage.observe(|| {
            rstyle_pdg::unit_store::read_diagnostic_snapshot_headers_phase(
                snapshot.bundle.bytes(),
                "compiler-advisory-only",
            )
        })?;
        consume_facts(
            Decoded {
                facts,
                owner: FactOwner::Numeric,
            },
            request,
            &snapshot,
            result,
        )
    } else {
        let facts = stage.observe(|| {
            rstyle_pdg::unit_store::read_diagnostic_snapshot_phase(
                snapshot.bundle.bytes(),
                "compiler-advisory-only",
            )
        })?;
        consume_facts(
            Decoded {
                facts,
                owner: FactOwner::Advisory,
            },
            request,
            &snapshot,
            result,
        )
    }
}

fn consume_facts<B: identity::BodyOwner>(
    decoded: Decoded<B>,
    request: &UnitRequest<'_>,
    snapshot: &capture::Snapshot,
    result: &mut Handoff,
) -> Result<(), String> {
    let Decoded { facts, owner } = decoded;
    let unit = request.unit;
    let context_stage = Stage::new("cli.advisory.context", &unit.target.package, None).enter();
    let selected = selected_context::SelectedContext::new(unit)?;

    let mut builds = rstyle_pdg::nominal_binding::BuildContexts::default();
    for function in &facts {
        verify_frontend_invocation(function, unit, request.capture, &selected)?;
        builds.intern(&function.build)?;
    }

    result
        .source_inventory
        .extend(source_inventory(unit, snapshot)?);
    result.build_contexts.push(UnitBuildContexts {
        unit_bundle: unit.directory.join("unit.evidence.json"),
        builds,
    });
    context_stage.finish(Ok::<_, String>(()))?;
    Stage::new("cli.advisory.retain", &unit.target.package, None).observe(|| {
        let keys = identity::functions(request.id, &facts)?;
        retain(owner(Arc::new(facts)), keys, request, result)
    })
}

pub(super) fn configuration(args: &Args) -> Result<Option<Config>, String> {
    if !args.source_rules && !args.guard_clauses && args.changed_files.is_none() {
        return Ok(None);
    }
    Ok(Some(Config {
        source: args.source_rules.then(|| source_policy(args)).transpose()?,
        guards: args.guard_clauses,
        changed_files: args
            .changed_files
            .as_deref()
            .map(changed_scope::Selection::load)
            .transpose()?,
    }))
}

fn selected_workspace(cli: &Cli) -> Result<crate::workspace::Metadata, String> {
    let metadata = crate::workspace::load_with_toolchain(
        cli.manifest_path.as_deref(),
        Some(&run::pinned_toolchain()),
    )?;
    if let Some(package) = metadata.unknown_packages(&cli.packages).first() {
        return Err(format!("unknown package {package}"));
    }
    Ok(metadata)
}

fn tool_identity(tool: &str, argument: &str) -> Result<String, String> {
    let output = Command::new(tool)
        .arg(argument)
        .env("RUSTUP_TOOLCHAIN", run::pinned_toolchain())
        .output()
        .map_err(|e| e.to_string())?;

    if !output.status.success() {
        return Err(format!("cannot determine pinned {tool} identity"));
    }
    Ok(String::from_utf8_lossy(&output.stdout).trim().to_owned())
}

fn targets(
    cli: &Cli,
    profile: rstyle_pdg::extraction_profile::ExtractionProfile,
) -> Result<Vec<Target>, String> {
    let mut command = Command::new("cargo");
    command
        .args(["metadata", "--format-version", "1", "--no-deps"])
        .env("RUSTUP_TOOLCHAIN", run::pinned_toolchain());
    if let Some(path) = &cli.manifest_path {
        command.arg("--manifest-path").arg(path);
    }

    let output = command.output().map_err(|e| e.to_string())?;
    if !output.status.success() {
        return Err(String::from_utf8_lossy(&output.stderr).into());
    }
    let value: Value = serde_json::from_slice(&output.stdout).map_err(|e| e.to_string())?;
    selected_targets(&value, cli, profile)
}

fn expected_units(capture: &Capture, cli: &Cli, args: &Args) -> Result<Value, String> {
    let output = command(capture, cli, args)?
        .args(["--unit-graph", "-Z", "unstable-options"])
        .output()
        .map_err(|e| e.to_string())?;
    if !output.status.success() {
        return Err(format!(
            "Cargo compilation planning failed: {}",
            String::from_utf8_lossy(&output.stderr)
        ));
    }
    let graph: Value = serde_json::from_slice(&output.stdout).map_err(|e| e.to_string())?;

    if graph["version"] != 1 || !graph["units"].is_array() {
        return Err("unsupported Cargo unit graph".into());
    }
    write_json(&capture.directory.join("expected-unit-graph.json"), &graph)?;
    Ok(graph)
}

fn capture_unit(
    plan: &Path,
    target: Target,
    invocation: Vec<String>,
    mut command: Command,
) -> Result<u8, String> {
    if invocation
        .iter()
        .any(|arg| arg.starts_with("incremental=") || arg.starts_with("-Cincremental="))
    {
        return Err("strict capture requires incremental compilation disabled; remove explicit -C incremental flags".into());
    }
    let root = plan.parent().ok_or("missing run directory")?;
    let selected_plan: Plan = read_json(plan)?;
    let directory = tempfile::Builder::new()
        .prefix("invocation-")
        .tempdir_in(root)
        .map_err(|e| e.to_string())?
        .keep();
    let test = invocation.iter().any(|a| a == "--test");
    let unit = Unit {
        compiler_advisory_only: selected_plan.compiler_advisory_only,
        extraction_profile: selected_plan.extraction_profile,
        target,
        test,
        invocation,
        directory,
        artifacts: Vec::new(),
    };
    let status = invoke_unit(&unit, &mut command)?;

    if !status.success() {
        return Ok(2);
    }
    publish_unit(&selected_plan, root, unit)?;
    Ok(0)
}

fn read_artifact(directory: &Path, file: String) -> Result<Artifact, String> {
    if file == "unit.evidence.json" {
        let bytes = std::fs::read(directory.join("unit.evidence.manifest.json"))
            .map_err(|error| error.to_string())?;
        let manifest: rstyle_pdg::unit_store::BundleManifest =
            serde_json::from_slice(&bytes).map_err(|error| error.to_string())?;
        return Ok(Artifact {
            file,
            checksum: manifest.checksum,
        });
    }
    let bytes = std::fs::read(directory.join(&file)).map_err(|error| error.to_string())?;
    Ok(Artifact {
        file,
        checksum: rstyle_pdg::unit_store::transport_checksum(&bytes),
    })
}

fn associate_call(
    context: &CallContext<'_, '_>,
    caller: usize,
    resolution: &Value,
    output: &mut Output,
) -> Result<(), String> {
    let name = string(resolution, "crate")?;
    if !context.routes.crates.contains_key(name) {
        return Ok(());
    }
    let foreign = resolution
        .get("compiled_dependency")
        .ok_or("Selected dependency call lacks compiler identity")?;
    associate_foreign(
        context,
        caller,
        ForeignCrate {
            name,
            observation: foreign,
        },
        output,
    )
}

fn seal(path: &Path, seals: &mut Seals) -> Result<ArtifactSeal, String> {
    if let Some(seal) = seals.get(path) {
        return Ok(seal.clone());
    }

    let bytes = std::fs::read(path)
        .map_err(|error| format!("Missing emitted dependency rmeta: {error}"))?;
    let result = ArtifactSeal {
        bytes: u64::try_from(bytes.len()).map_err(|_| "Oversized dependency rmeta")?,
        checksum: rstyle_pdg::unit_store::transport_checksum(&bytes),
        crate_hash: native_crate_hash(&bytes)?,
    };

    seals.insert(path.to_owned(), result.clone());
    Ok(result)
}

pub(in crate::clones::capture) fn select(
    graph: &Value,
    cli: &Cli,
    args: &Args,
) -> Result<Vec<super::Selected>, String> {
    if args.capture_dependencies.is_empty() {
        return Ok(Vec::new());
    }

    let mut command = Command::new("cargo");
    command
        .args(["metadata", "--format-version", "1"])
        .env("RUSTUP_TOOLCHAIN", run::pinned_toolchain())
        .args(options(cli, args));

    let output = command.output().map_err(|error| error.to_string())?;
    if !output.status.success() {
        return Err(format!(
            "Dependency metadata resolution failed: {}",
            String::from_utf8_lossy(&output.stderr)
        ));
    }

    let metadata: Value =
        serde_json::from_slice(&output.stdout).map_err(|error| error.to_string())?;
    if metadata.get("version").and_then(Value::as_u64) != Some(1) {
        return Err("Unsupported resolved dependency metadata version".into());
    }

    super::select(
        &metadata,
        graph,
        super::Selection {
            requests: &args.capture_dependencies,
            profile: args.extraction_profile,
            target: args.target.as_deref(),
        },
    )
}

fn restart(capture: &mut Capture) -> Result<(), String> {
    let parent = capture.directory.parent().ok_or("Missing capture parent")?;
    capture.directory = tempfile::Builder::new()
        .prefix("run-")
        .tempdir_in(parent)
        .map_err(|e| e.to_string())?
        .keep();

    capture.units.clear();
    capture.failures.clear();
    write_json(&capture.directory.join("plan.json"), &capture.plan)?;
    write_json(
        &capture.directory.join("expected-unit-graph.json"),
        &capture.expected_unit_graph,
    )
}

fn manifest(directory: &Path) -> Result<Manifest, String> {
    let manifest: Manifest = read_json(&directory.join(FILE))?;
    if manifest.schema != SCHEMA
        || manifest.ledgers.is_empty()
        || manifest.ledgers.len() != manifest.namespaces.len()
    {
        return Err("Invalid saved dependency closure inventory".into());
    }
    Ok(manifest)
}

pub(super) fn consume(
    capture: &capture::Capture,
    args: &Args,
    assignments: &[identity::Assignment<'_>],
    result: &mut Handoff,
) -> Result<(), String> {
    let requests = requests(capture, args, assignments)?;
    // Keep ledger ordinals distinct from sorted report unit IDs.
    let (stores, bindings): (Vec<_>, Vec<_>) = requests
        .iter()
        .map(|request| load_unit(request, result))
        .collect::<Result<Vec<_>, _>>()?
        .into_iter()
        .unzip();

    let checked = check_closure(capture, args, &stores)?;
    let closure =
        DependencyClosure::from_units_with(stores, &checked.associations, |_, claims| {
            if claims != checked.associations {
                return Err("Dependency association claims changed after validation".into());
            }
            Ok(())
        })?;

    consume_closure(&closure, bindings, &requests, result)?;
    if args.replay_run.is_none() {
        write_json(&capture.directory.join(FILE), &checked)?;
    }
    Ok(())
}

fn check_closure(
    capture: &capture::Capture,
    args: &Args,
    stores: &[UnitStore],
) -> Result<Manifest, String> {
    let observations: Vec<_> = stores
        .iter()
        .map(|store| ObservedUnit {
            namespace: *store.namespace(),
            functions: store.functions(),
        })
        .collect();

    let cargo = cargo_artifacts(&capture.directory)?;
    let associations = capture::associations::associate(Request {
        graph: &capture.expected_unit_graph,
        cargo: &cargo,
        units: &capture.units,
        observations: &observations,
    })?;

    let checked = Manifest {
        schema: SCHEMA.into(),
        ledgers: capture
            .units
            .iter()
            .map(|unit| {
                capture::ledger::path(&capture.plan, &capture.directory, &unit.target, unit.test)
            })
            .collect::<Result<_, _>>()?,
        namespaces: observations.iter().map(|unit| unit.namespace).collect(),
        associations,
    };
    if args.replay_run.is_some() && manifest(&capture.directory)? != checked {
        return Err(
            "Saved dependency closure disagrees with independently checked artifacts".into(),
        );
    }
    Ok(checked)
}

fn cargo_artifacts(directory: &Path) -> Result<Vec<Value>, String> {
    let file = std::fs::File::open(directory.join("cargo.jsonl")).map_err(|e| e.to_string())?;
    let reader = std::io::BufReader::new(file);
    let records: Vec<Value> = serde_json::Deserializer::from_reader(reader)
        .into_iter()
        .collect::<Result<_, _>>()
        .map_err(|e| e.to_string())?;

    let completion = records
        .last()
        .ok_or("Dependency closure lacks Cargo completion")?;
    if completion["reason"] != "build-finished" || completion["success"] != true {
        return Err("Dependency closure lacks successful Cargo completion".into());
    }
    Ok(records)
}

pub(in crate::clones) fn publish_optional<T: Inventory, H>(
    report: Option<&Report<T, H>>,
    path: Option<&Path>,
    complete: bool,
) -> Result<(), String> {
    if let Some(path) = path {
        report
            .ok_or_else(|| format!("{} was not evaluated", T::LABEL))?
            .publish(path, complete)?;
    }
    Ok(())
}

pub(super) fn write(path: &Path, bytes: &[u8], mode: Mode) -> Result<(), String> {
    let directory = path
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
        .unwrap_or(Path::new("."));
    let mut file = tempfile::NamedTempFile::new_in(directory).map_err(|error| error.to_string())?;
    file.write_all(bytes).map_err(|error| error.to_string())?;
    file.flush().map_err(|error| error.to_string())?;

    let result = match mode {
        Mode::Replace => file.persist(path),
        Mode::CreateNew => file.persist_noclobber(path),
    };
    result.map_err(|error| format!("{}: {error}", path.display()))?;
    Ok(())
}

fn dismiss_one(
    store: &mut ReviewStore,
    row: &observed::Row,
    family: Family,
    reason: &str,
) -> Result<(), String> {
    let required_schema = record_choice(store, row, family, reason)?;
    store.schema_version = store.schema_version.max(required_schema);
    Ok(())
}

/// One load and atomic publication across all requested review families.
    /// A failed selector or snapshot leaves every retained entry untouched on disk.
    pub(in crate::clones) fn apply(
        self,
        ctx: &report::Context<'_>,
        mut store: Option<ReviewStore>,
    ) -> Result<Reports, String> {
        let mut reports = evaluate(&self, ctx, store.as_mut())?;
        reports.pruning = pruning(store.as_mut(), reports.status.as_ref(), ctx)?;

        if (!ctx.args.dismiss_helper_pair.is_empty()
            || ctx.args.dismiss_enum_dispatch.is_some()
            || !ctx.args.dismiss_capability_pair.is_empty()
            || ctx.args.dismiss_parameter.is_some()
            || ctx.args.dismiss_length.is_some()
            || ctx.args.dismiss_spacing.is_some()
            || ctx.args.dismiss_mutation_per_target.is_some()
            || ctx.args.dismiss_mutated_targets.is_some()
            || ctx.args.dismiss_density.is_some()
            || !ctx.args.dismiss_compiler_pattern.is_empty()
            || !ctx.args.import_legacy_pattern.is_empty()
            || !ctx.args.dismiss_compiler_diagnostic.is_empty()
            || !ctx.args.dismiss_guard.is_empty()
            || reports
                .pruning
                .as_ref()
                .is_some_and(|report| report.removed_entries > 0))
            && let (Some(path), Some(store)) = (&ctx.args.review_file, &store)
        {
            save(path, store)?;
        }
        Ok(reports)
    }

fn streamed_output(command: &mut Command) -> io::Result<Output> {
    command
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    let mut child = command.spawn()?;
    let stdout = child
        .stdout
        .take()
        .ok_or_else(|| io::Error::other("missing stdout pipe"))?;
    let stderr = child
        .stderr
        .take()
        .ok_or_else(|| io::Error::other("missing stderr pipe"))?;
    let captured = std::thread::scope(|scope| {
        let stdout = scope.spawn(|| collect(stdout));
        let stderr = tee(stderr);
        let stdout = stdout
            .join()
            .map_err(|_| io::Error::other("stdout reader panicked"))?;
        Ok::<_, io::Error>((stdout?, stderr?))
    });
    let status = child.wait()?;
    let (stdout, stderr) = captured?;

    Ok(Output {
        status,
        stdout,
        stderr,
    })
}

fn session(cli: &Cli, args: &IgnoreArgs) -> Result<Session, String> {
