fn install_signature(
        &mut self,
        facts: &mut HirFnFacts,
        interface: &InterfaceObservations,
    ) -> Result<(), String> {
        if self.ctx.profile.supports("rust.concrete-read-only-data") {
            interface_tokens(&mut facts.signature, interface)?;
            // Local consumers join the signature to its original binding.
            // Reuse this capture's completed types without enriching the body.
            self.binding_tokens(&mut facts.bindings, true)?;
        }
        Ok(())
    }

fn interface_tokens(
    signature: &mut rstyle_pdg::SignatureFacts,
    interface: &InterfaceObservations,
) -> Result<(), String> {
    for (parameter, observation) in signature.params.iter_mut().zip(&interface.parameters) {
        if let Observation::Captured { ty } = observation {
            parameter.ty.normalized = Some(rstyle_pdg::data_types::token(ty)?);
            parameter.pat.ty = Some(parameter.ty.clone());
        }
    }

    if let Observation::Captured { ty } = &interface.result {
        signature.return_ty.normalized = Some(rstyle_pdg::data_types::token(ty)?);
    }
    Ok(())
}

fn callback_environments_in(
        &mut self,
        node: &mut HirNode,
        owner: Option<&rstyle_pdg::HirRef>,
    ) -> Result<(), String> {
        // Unsupported bodies retain actual captures and explicit unknown storage.
        if node.kind == "expr_closure" && !node.children.is_empty() {
            node.res = Some(self.callback_environment(node, owner == Some(&node.hir))?);
        }
        let callback = immediate_map_or_callback(node);
        node.children
            .iter_mut()
            .try_for_each(|child| self.callback_environments_in(child, callback.as_ref()))
    }

fn import(&mut self, site: Site, target: DefId) -> Result<(), String> {
        let Some(artifact) = crate_association::namespace_artifact(self.context.tcx, target) else {
            return self
                .context
                .unsupported(target, "Foreign namespace lacks loaded metadata artifact");
        };
        let inventory = self.import_inventory(target)?;

        self.context.output.imports.push(Import {
            site,
            compiled_dependency: serde_json::to_value(artifact)
                .map_err(|error| error.to_string())?,
            exports: inventory.exports,
            complete: inventory.complete,
        });
        Ok(())
    }

fn signature_types<'tcx>(
    signature: ty::FnSig<'tcx>,
    observe: &mut impl FnMut(Ty<'tcx>) -> Result<Observation, String>,
) -> Result<(Vec<Observation>, Observation), String> {
    let inputs = signature
        .inputs()
        .iter()
        .map(|ty| observe(*ty))
        .collect::<Result<_, _>>()?;

    let output = observe(signature.output())?;

    Ok((inputs, output))
}

pub(crate) fn capture(
    tcx: TyCtxt<'_>,
    scanned: &[source::Function],
    options: &Options<'_>,
) -> Result<(), String> {
    let Some(path) = std::env::var_os("RSTYLE_DIAGNOSTIC_PRODUCT_INSTANCE_REQUESTS") else {
        return Ok(());
    };
    let requests: Requests =
        serde_json::from_reader(std::fs::File::open(path).map_err(|error| error.to_string())?)
            .map_err(|error| error.to_string())?;
    validate(&requests, tcx, options)?;
    let owners = diagnostic_support::owners(tcx, &[DefKind::AssocFn]);
    let entries = requests
        .requests
        .into_iter()
        .map(|request| {
            let outcome = match owners.get(&request.function).copied().flatten() {
                Some(owner) => observe_owner(tcx, owner, &request, Inputs { scanned, options }),
                None => Outcome::Unavailable {
                    reason: "Original associated owner is unavailable or ambiguous".into(),
                },
            };
            Entry { request, outcome }
        })
        .collect();

    diagnostic_support::persist(
        &Inventory {
            identity: "rstyle.diagnostic.product-instance-bodies/1",
            scope: "original associated Match constructor, Span/Range substitutions and selected Into/From observations only",
            admission_authority: false,
            requests: entries,
        },
        "product-instances",
        "Product diagnostics require an explicit snapshot directory",
    )
}

pub(crate) fn capture(
    tcx: TyCtxt<'_>,
    scanned: &[source::Function],
    options: &Options<'_>,
) -> Result<(), String> {
    let Some(path) = std::env::var_os("RSTYLE_DIAGNOSTIC_REFERENCE_INSTANCE_REQUESTS") else {
        return Ok(());
    };

    let requests: Requests =
        serde_json::from_reader(std::fs::File::open(path).map_err(|error| error.to_string())?)
            .map_err(|error| error.to_string())?;
    validate(&requests, tcx, options)?;

    let owners = diagnostic_support::owners(tcx, &[DefKind::Fn, DefKind::AssocFn]);
    let entries = requests.requests.into_iter().map(|request| {
        let outcome = match owners.get(&request.function).copied().flatten() {
            Some(id) => observe(Owner { tcx, id }, &request, scanned, options),
            None => Outcome::Unavailable {
                reason: "Original owning function is absent or ambiguous".into(),
            },
        };
        Entry { request, outcome }
    });

    diagnostic_support::persist(
        &Inventory {
            identity: "rstyle.diagnostic.reference-instance-bodies/1",
            scope: "original owning-body observations only; no lifetime, cleanup, origin, artifact or admission authority",
            admission_authority: false,
            requests: entries.collect(),
        },
        "reference-instances",
        "Reference diagnostics require an explicit snapshot directory",
    )
}

pub fn crate_facts(
    tcx: TyCtxt<'_>,
    scanned: &[source::Function],
    options: &Options<'_>,
) -> Result<rstyle_pdg::unit_store::UnitStore, String> {
    let facts = raw_crate_facts(tcx, scanned, options)?;
    diagnostics::snapshot("pre-helper-certification", &facts)?;
    let store = rstyle_pdg::unit_store::UnitStore::capture(facts)?;
    diagnostics::snapshot("post-helper-certification", store.functions())?;

    Ok(store)
}

fn install_one(
    pair: &mut Pair,
    installation: &mut Installation,
    prepared: Prepared,
) -> Result<(), String> {
    let node = &mut pair.pdg.nodes[prepared.position];
    if installation.definitions.nodes.contains(&node.id) {
        return Err("Mutable access already owns a definition".into());
    }
    if let Some(definition) = install_effect(node, &prepared.site, &prepared.id)? {
        if !installation.definitions.ids.insert(definition.id.clone()) {
            return Err("Mutable definition ID collides".into());
        }
        pair.pdg.definitions.push(definition);
    }
    installation
        .locations
        .insert(prepared.id, prepared.location);

    Ok(())
}

fn install_node(
    pair: &mut Pair,
    source: &HirNode,
    effects: Effects,
) -> Result<BTreeMap<String, MemoryLocation>, String> {
    let node = super::serialized_operation_mut(pair, source)?;
    node.attributes.reads = effects.reads;
    node.annotations.extend(effects.annotations);

    Ok(effects.locations)
}

pub fn get_mut(&mut self, key: &str) -> Option<&mut Value> {
        let entry = self.0.get_mut(key)?;
        if !matches!(entry, Entry::Json(_)) {
            let original = std::mem::replace(entry, Entry::Json(Value::Null));
            *entry = Entry::Json(original.into_json());
        }
        let Entry::Json(value) = entry else {
            unreachable!()
        };
        Some(value)
    }

pub(crate) fn intern_census(
        &mut self,
        owners: &mut Vec<Arc<crate::nominal_boundary::census::Census>>,
    ) -> Result<(), String> {
        let Some(Entry::Census(record)) = self.0.get_mut(crate::nominal_boundary::census::KEY)
        else {
            return Ok(());
        };
        record.value = intern_owner(&record.value, owners)?;
        Ok(())
    }

pub(super) fn certify(
    facts: &dyn EvidenceFacts,
) -> Result<Option<(Summary, producer::Pair)>, String> {
    // A raw match shape cannot substitute for the complete source receipt.
    if activation::verify(facts).is_err() {
        return Ok(None);
    }
    let pair = producer::produce(facts).map_err(|errors| errors.join("; "))?;
    let summary = crate::diagnostics::Stage::new("helper.digit-product-summary", &facts.name, None)
        .observe(|| derive(facts, &pair))?;

    Ok(Some((summary, pair)))
}

fn unpack(&mut self, index: usize, depth: usize) -> Result<Value, String> {
        check_depth(depth)?;
        let fields = self
            .nodes
            .get(index)
            .and_then(Value::as_array)
            .ok_or("Missing or malformed helper transport node")?
            .clone();
        self.used.insert(index);
        self.charge(1)?;

        self.value(&fields, index, depth)
    }

fn value(&mut self, fields: &[Value], index: usize, depth: usize) -> Result<Value, String> {
        match fields.first().and_then(Value::as_str) {
            Some("literal")
                if fields.len() == 2 && !fields[1].is_object() && !fields[1].is_array() =>
            {
                self.charge(fields[1].as_str().map_or(1, str::len))?;
                Ok(fields[1].clone())
            }
            Some("json" | "quoted") => self.encoded_string(fields, index, depth),
            Some("text" | "array" | "object") if fields.len() == 2 => {
                self.collection(fields, index, depth)
            }
            _ => Err("Unsupported or malformed helper transport tag".into()),
        }
    }

fn collection(
        &mut self,
        fields: &[Value],
        index: usize,
        depth: usize,
    ) -> Result<Value, String> {
        match fields[0].as_str() {
            Some("array") => {
                let ids = fields[1]
                    .as_array()
                    .ok_or("Malformed helper transport array")?;
                ids.iter()
                    .map(|id| self.child(id, index, depth))
                    .collect::<Result<_, _>>()
                    .map(Value::Array)
            }
            Some("text") => self.text(&fields[1], index, depth),
            Some("object") => self.object(&fields[1], index, depth),
            _ => Err("Malformed helper transport collection tag".into()),
        }
    }

fn select_copies(
        &mut self,
        facts: &HirFnFacts,
        origins: &declaration_origins::Origins,
        owner: Option<&crate::product_instances::CheckedProjection>,
    ) -> Result<(), String> {
        let selected = selected::verify(facts, origins, self, owner)?;
        self.copy_trees = selected.copies;
        self.no_drop_trees = selected.no_drop;
        self.source_requirements = selected.requirements;

        Ok(())
    }

fn begin_module(
        &mut self,
        environment: &Environment,
        module: &census::Module,
    ) -> Result<(), String> {
        self.enums.namespace = module.namespace.clone();
        self.definitions = inherited(&environment.modules, &module.namespace, &self.configuration)?;
        self.scopes = vec![self.scope(module.items.iter())?];
        Ok(())
    }

fn install_binding(&mut self, binding: &BindingFact, value: Value) -> Result<()> {
        self.bindings.insert(binding.symbol.clone());
        self.scope
            .entry(binding.name.clone())
            .or_default()
            .push(Binding {
                hir: binding.hir.clone(),
                value,
            });
        self.frames
            .last_mut()
            .ok_or("Missing scalar lexical frame")?
            .push(binding.name.clone());
        Ok(())
    }

fn load_bundle(
        bytes: &[u8],
        inspect: impl FnOnce(&[HirFnFacts]) -> Result<(), String>,
        current_run: bool,
    ) -> Result<Self, String> {
        let import = crate::diagnostics::Stage::new("unit.decode", "bundle", None)
            .observe(|| Import::decode(bytes))?;
        crate::diagnostics::Stage::new("unit.inspect", "bundle", None)
            .observe(|| inspect(&import.functions))?;

        let store = crate::diagnostics::Stage::new("unit.structure", "bundle", None)
            .observe(|| import.into_store())?;
        if current_run {
            crate::verification_policy::generated(|| {
                crate::diagnostics::Stage::new("unit.verify", "bundle", None)
                    .observe(|| store.validate_evidence())
            })?;
        } else {
            crate::verification_policy::strict(|| {
                crate::diagnostics::Stage::new("unit.verify", "bundle", None)
                    .observe(|| store.validate_evidence())
            })?;
        }
        Ok(store)
    }

fn install_dependency_owners(
    builder: &mut Builder,
    index: usize,
    plan: &Plan,
    completed: &[Option<Arc<UnitStore>>],
) -> Result<(), String> {
    builder.store.dependencies = linked_dependencies(index, plan, completed)?;
    builder.store.namespace_associations = plan.namespace_associations[index]
        .iter()
        .enumerate()
        .map(
            |(dependency, observation)| dependency_namespaces::Association {
                dependency,
                compiled_dependency: observation.clone(),
            },
        )
        .collect();

    Ok(())
}

/// Seal the exact streamed publication bytes only after its final flush succeeds.
pub(super) fn seal<W: Write>(
    writer: W,
    publish: impl FnOnce(&mut dyn Write) -> Result<(), String>,
) -> Result<BundleManifest, String> {
    let mut recorder = Recorder {
        writer,
        hash: Xxh3::new(),
        bytes: 0,
    };
    publish(&mut recorder)?;
    recorder.flush().map_err(|error| error.to_string())?;

    Ok(BundleManifest {
        schema: SCHEMA.into(),
        checksum: encode(recorder.hash.digest()),
        bytes: recorder.bytes,
    })
}

fn install(
        self,
        store: &mut UnitStore,
        origin: OriginalInstance<SpanArgument>,
        checked: CheckedProjection,
    ) -> Result<(), String> {
        install_dependency(store, &origin, &checked, self.observation)?;
        store.product_instance = Some(ProductInstanceRecord {
            origin,
            checked,
            observation: self.observation.clone(),
        });
        Ok(())
    }
